import{_ as r,C as n,o as s,c as d,j as e,a,E as i,ag as c}from"./chunks/framework.HG0H2VLS.js";const f=JSON.parse('{"title":"ContractAnalysis","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/contract-analysis.md","filePath":"cc-templates/contract-analysis.md"}'),l={name:"cc-templates/contract-analysis.md"};function h(u,t,p,g,m,y){const o=n("ComponentDemo");return s(),d("div",null,[t[0]||(t[0]=e("hr",null,null,-1)),t[1]||(t[1]=e("h2",{id:"title-contractanalysis",tabindex:"-1"},[a("title: ContractAnalysis "),e("a",{class:"header-anchor",href:"#title-contractanalysis","aria-label":'Permalink to "title: ContractAnalysis"'},"​")],-1)),t[2]||(t[2]=e("h1",{id:"contractanalysis",tabindex:"-1"},[a("ContractAnalysis "),e("a",{class:"header-anchor",href:"#contractanalysis","aria-label":'Permalink to "ContractAnalysis"'},"​")],-1)),t[3]||(t[3]=e("blockquote",null,[e("p",null,[e("code",null,"/control/contract-analysis"),a(" on v3: RecordTabs (Contract overview / Top accounts / Outstanding amounts / Monthly review under "),e("code",null,"?Navigation="),a("), StatCard KPIs, 12 Chart")])],-1)),i(o,{src:"/demos/src/cc/templates/ContractAnalysis/ContractAnalysis.html"}),t[4]||(t[4]=c('<h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>From</th></tr></thead><tbody><tr><td>Shell</td><td>ControlScreen. Breadcrumb Zone Selector › CRM › Contract Analysis (menu: CRM › Analysis); title only</td></tr><tr><td>Tabs</td><td>RecordTabs. Hrefs keep classic&#39;s <code>?Navigation=Contract|TopAccounts|Outstanding|Review</code>; switched in place (<code>replaceState</code>)</td></tr><tr><td>KPIs</td><td>StatCard: Xl (Overview), Base (other tabs), solid fills; <code>--lagoon</code> where it was blue (designer, 2026-10-02); <code>*-pound-sterling</code> icons for money</td></tr><tr><td>Charts</td><td>Chart pattern + Chart.js. The headline (<code>chart__big</code>) is the window total. <strong>Overview (designer, 2026-10-02):</strong> value charts accent <strong>lagoon</strong> (Lagoon/9), count charts accent <strong>purple</strong> (Purple/600), at <code>size-6</code> (designer, 2026-10-07; lagoon/purple is deutan ΔE 16.0 and passes both themes. History: blue/purple failed at ΔE 2.5, so blue/orange ran 2026-10-05 → 10-07). <strong>Monthly review (designer, 2026-10-02):</strong> Flowbite-style distinct hues: two-series charts use accent <strong>lagoon + purple</strong> (designer, 2026-10-07; was blue + orange); groups use lagoon, purple, emerald, orange, blue, pink, plus <code>text-contrast</code> for Other (passes the validator in both themes: worst adjacent protan ΔE 10.1, normal 28.6; emerald/pink are ΔE 1.1 and emerald/lagoon normal 11.9, so neither pair is adjacent; purple is 2.72:1 on the dark card, relieved by the legend and the month tables) (brand teal next to jade was too close to tell apart). Canvases are bigger there: <code>size-6</code> two-up, <code>size-7</code> full width. The tooltip uses <code>surface-invert</code>. <strong>Bars (designer, 2026-10-02):</strong> one shape everywhere: a 4px radius on the outer end only (top, or the right end when horizontal), a flat base, and on stacked charts only the topmost visible segment rounded <strong>Month-to-date contracts (designer, 2026-10-07):</strong> not a daily bar chart (a 0/1 count drew identical full-height bars) but a stepped running total for this month (purple, stops at today) against last month by the same day (<code>--ai-text-contrast</code>, dashed, behind). Headline = contracts so far; the sub-line gives last month&#39;s count by today&#39;s day; tooltip title is the date. Grey fails the chroma check by design (recessive reference); purple vs grey passes CVD (deutan 18.4 light / 23.3 dark). <strong>Same form on the 12-month contract chart</strong> (designer, 2026-10-07): monthly running total vs the previous 12 months, the current month to date and the comparison cut at the same day (like for like); the grey reference is drawn only when the previous period has contracts. The <strong>5-year</strong> contract chart stays a bar per year (tried as a running total, reverted: over five years it only climbs).</td></tr><tr><td>Filters</td><td>Input (search) + Select <code>--sm</code> + DatePicker (range), in one card per tab, inline (Flowbite-style), with a Reset</td></tr><tr><td>Tables</td><td>Datatables <code>--orders</code> + Table (as every listing), <code>datatables__record-link</code>, sortable headers (<code>aria-sort</code>), &quot;Show n more&quot;</td></tr><tr><td>Status</td><td>Badge, base size (designer, 2026-10-02; was <code>--sm</code>): payment (Paid success · In Arrears danger · Written Off neutral · else warning); expiry (OK success · One-off neutral · Upcoming warning · Imminent / Expired danger)</td></tr></tbody></table><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Shows</th></tr></thead><tbody><tr><td>Contract overview</td><td>3 KPIs: Total contract value, Customers, <strong>Ave. value per customer</strong>. 6 charts, two-up: value (filled line) and count (bar) for this month by day, the last 12 months, and the last 5 years (current year YTD). No filters</td></tr><tr><td>Top accounts</td><td>Filters: account search, account type, contract type, industry, date range (All time + 8 presets + Custom range). KPIs: Accounts, Contracts, Value. <strong>Top 10 as a horizontal bar.</strong> Table: Account, Industry, Account type, Contracts, First, Latest, Monthly ave., Total (default Total ↓), 20 at a time</td></tr><tr><td>Outstanding amounts</td><td>Filters: search, account type, contract type. KPIs: Outstanding, Contracts, In arrears. Table: Contract, Account, Amount, <strong>Outstanding</strong> (default ↓), Payment status, Term, Status, Created</td></tr><tr><td>Monthly review</td><td>Filters: search, account type, contract type, owner, industry. Charts: last 12 months vs the year before (line); new business vs renewal value (line); <strong>new business vs renewals per-month 100% split</strong> (stacked bar); by industry and by owner (stacked bar, <strong>top 6 by value + Other</strong>; each hidden when filtered to one). Then 6 month tables, newest first, each with a title, count and £ total</td></tr></tbody></table><h2 id="data-rules-one-definition-every-tab" tabindex="-1">Data rules (one definition, every tab) <a class="header-anchor" href="#data-rules-one-definition-every-tab" aria-label="Permalink to &quot;Data rules (one definition, every tab)&quot;">​</a></h2><p>A contract counts when it&#39;s <strong>not cancelled and not archived</strong>. Top accounts additionally excludes PaymentStatus Cancelled. Outstanding = OutstandingAmount &gt; 0 and not Paid. Classic disagreed tab to tab: Overview counted archived; Top Accounts excluded PaymentStatus 7 only; Outstanding&#39;s list included cancelled contracts while its total didn&#39;t.</p><h2 id="classic-errors-fixed-flag-for-the-backend-to-match" tabindex="-1">Classic errors fixed (flag for the backend to match) <a class="header-anchor" href="#classic-errors-fixed-flag-for-the-backend-to-match" aria-label="Permalink to &quot;Classic errors fixed (flag for the backend to match)&quot;">​</a></h2><ol><li>&quot;AVE. CONTRACT VALUE&quot; was total ÷ customers → <strong>&quot;Ave. value per customer&quot;</strong>.</li><li>Top 10 was a <code>line</code> chart over account names → horizontal bar. Classic&#39;s ValueList also broke on names containing commas.</li><li>Contract Type (Top Accounts) and Account Type (Outstanding) were rendered but never applied → applied.</li><li>&quot;New Business / Renewals Percentage&quot; divided by the 12-month total (no month summed to 100) → per-month split.</li><li>By-industry / by-owner were <code>TOP 20</code> with no ORDER BY → top 6 by value + Other.</li><li>Date From + Date To + a preset select → one Date range control with Custom range (a DatePicker range).</li><li>Outstanding&#39;s &quot;Amounts&quot; cell held <code>£12000.00&lt;br&gt;(£4000.00)</code>, unformatted → separate formatted Amount and Outstanding columns.</li><li>Type, Renewal and Media are dropped from the tables (the name carries the type; Term says One-off).</li><li>Counts are bars and values are filled lines (classic drew all six as identical grey lines with hardcoded <code>#3E4751</code>, fixed px canvases and fixed <code>yStepSize</code>).</li></ol><p><strong>Also for Lynx (classic bugs found while reading):</strong></p><ul><li>Outstanding may <code>cflocation</code> to Contracts.cfm, because ContractQDef defaults <code>AMethod</code> to &quot;v&quot;. Check on live.</li><li>The Account autocomplete writes the account <strong>code</strong> into a <code>Name LIKE</code> filter.</li><li>Sorting Top Accounts drops Date From / Date To (they aren&#39;t in <code>passcodes</code>).</li><li>Monthly Review calls a Highcharts chart whose div is commented out (likely a JS error), and loads both Highcharts and Chart.js.</li><li><code>fmonth</code> moves the tables but not the charts.</li><li>Monthly Review runs typically 60–80+ queries.</li></ul><h2 id="currency" tabindex="-1">Currency <a class="header-anchor" href="#currency" aria-label="Permalink to &quot;Currency&quot;">​</a></h2><p>Classic sums <code>Amount</code> across every currency under the CRM default prefix, with no conversion. The demo shows GBP only. <strong>The backend must either convert, or scope the figures to one currency</strong>, because a mixed sum is wrong.</p><h2 id="layout-values-all-borrowed-no-new-tokens" tabindex="-1">Layout values (all borrowed, no new tokens) <a class="header-anchor" href="#layout-values-all-borrowed-no-new-tokens" aria-label="Permalink to &quot;Layout values (all borrowed, no new tokens)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>From</th></tr></thead><tbody><tr><td>Page / panel / chart-grid / month-table gaps</td><td><code>spacing-5</code></td><td>RecordScreen card gap</td></tr><tr><td>KPI grid gap</td><td><code>spacing-4</code></td><td>Orders totals tiles</td></tr><tr><td>Filter card padding / fill / radius</td><td><code>spacing-4</code> × <code>spacing-5</code>, <code>surface-primary</code>, <code>radius-md</code></td><td>FilterBar row</td></tr><tr><td>Filter control gap</td><td><code>spacing-3</code></td><td>UpdateScreen action gap</td></tr><tr><td>Filter control fill</td><td><code>surface-minimal</code></td><td>Listing inputs</td></tr><tr><td>Select width</td><td><code>size-3</code> → <code>size-2</code></td><td>FieldRow label width</td></tr><tr><td>Search width</td><td><code>size-3</code> → <code>size-6</code> cap</td><td>—</td></tr><tr><td>Top 10 canvas height</td><td><code>size-6</code></td><td>—</td></tr><tr><td>Monthly review canvases</td><td><code>size-6</code> two-up, <code>size-7</code> wide</td><td>—</td></tr><tr><td>Full width</td><td>page padding <code>spacing-4</code>, gaps <code>spacing-4</code></td><td>Dashboard of cards, like SeatingPlanner&#39;s full-width empty states (not flush)</td></tr></tbody></table><p>Numbers are tabular but <strong>left-aligned</strong>, per the designer&#39;s demo rule (right-aligned is build-only).</p><h2 id="demo-data" tabindex="-1">Demo data <a class="header-anchor" href="#demo-data" aria-label="Permalink to &quot;Demo data&quot;">​</a></h2><p><code>contract-analysis-data.js</code>: 260 seeded contracts across 45 accounts over 5 years, with a fixed demo &quot;today&quot; of 26 Sep 2026 so &quot;this month&quot; has data. Everything on the page is computed from it in <code>ContractAnalysis.js</code>.</p>',17))])}const w=r(l,[["render",h]]);export{f as __pageData,w as default};
